// =============================================================
// WIDGET KOMMO: TASA DE CONVERSION COTIZACION GANADA
// =============================================================
// Logica:
//   - Leads ganados vs perdidos (con cotizacion) en el periodo
//   - Incluye desglose por usuario (responsible_user_id)
// =============================================================

const PIPELINE_VENTAS = 12677012;
const PIPELINE_RECURRENTES = 12676956;
const STAGE_WON_ID = 142;
const STAGE_LOST_ID = 143;
const FIELD_COTIZACION_ID = 1046555;

// Aplanar todas las paginas del HTTP Request
const leads = items.flatMap(i => i.json._embedded?.leads ?? []);

function tieneCotizacion(lead) {
  const field = lead.custom_fields_values?.find(f => f.field_id === FIELD_COTIZACION_ID);
  if (!field?.values?.length) return false;
  const valor = field.values[0].value;
  return valor !== null && valor !== undefined && String(valor).trim() !== '';
}

let countWon = 0;
let countLost = 0;
const porUsuario = {};

for (const lead of leads) {
  if (lead.pipeline_id !== PIPELINE_VENTAS && lead.pipeline_id !== PIPELINE_RECURRENTES) continue;
  if (!tieneCotizacion(lead)) continue;

  const uid = String(lead.responsible_user_id ?? 0);
  if (!porUsuario[uid]) porUsuario[uid] = { won: 0, lost: 0 };

  if (lead.status_id === STAGE_WON_ID) { countWon++; porUsuario[uid].won++; }
  else if (lead.status_id === STAGE_LOST_ID) { countLost++; porUsuario[uid].lost++; }
}

const totalCerrados = countWon + countLost;
const percentage = totalCerrados > 0 ? ((countWon / totalCerrados) * 100).toFixed(1) : '0.0';

const per_user = Object.entries(porUsuario).map(([uid, u]) => {
  const total = u.won + u.lost;
  const pct = total > 0 ? ((u.won / total) * 100).toFixed(1) : '0.0';
  return {
    user_id: uid,
    text_main: `${u.won} de ${total}`,
    text_sub: `${pct}%`,
    raw_won: u.won,
    raw_lost: u.lost
  };
}).sort((a, b) => b.raw_won - a.raw_won);

return [{
  json: {
    text_main: `${countWon} de ${totalCerrados}`,
    text_sub: `${percentage}%`,
    per_user,
    raw_won: countWon,
    raw_lost: countLost,
    raw_total: totalCerrados
  }
}];
